import { defineFolder } from '@storyblok/schema';

/*
 * Generated by `storyblok schema init`, with one correction: the CLI emitted
 * `parent: <the folder itself>` for every top-level folder, which is a
 * self-reference and throws "Cannot access 'x' before initialization" the
 * moment the schema is loaded. These folders have no parent, so the property
 * is omitted. Re-check this if the schema is ever re-initialised.
 */

export const blocksFolder = defineFolder({
  name: 'Blocks',
});

export const contentFolder = defineFolder({
  name: 'Content',
});

export const productsFolder = defineFolder({
  name: 'Products',
});
